        "output": "Html",
        "template": "<div class=\"container\">\n\n  <table class=\"header_date_section\">\n    <tr>\n      <td></td>\n      <td class=\"align_right\">Printed date: {{ now() | date(format=\"%m/%d/%Y\") }}</td>\n    </tr>\n    <tr>\n      <td></td>\n      <td class=\"align_right\">Entered date: {{ data.invoice.createdDatetime | date(format=\"%m/%d/%Y\") }}</td>\n    </tr>\n  </table>\n\n  <table class=\"body_section\" cellpadding=\"2\" cellspacing=\"0\">\n    <thead>\n      <tr class=\"body_column_label\">\n        <th class=\"line_number\" style=\"width: 5%\">Line</th>\n        <th class=\"location\" style=\"width: 10%\">Location</th>\n        <th class=\"item_code\" style=\"width: 10%\">Item code</th>\n        <th class=\"item_name\" style=\"width: 35%\">Item name</th>\n        <th class=\"quantity\" style=\"width: 5%\">Quantity</th>\n        <th class=\"issued\" style=\"width: 10%\">Issued</th>\n        <th class=\"pack\" style=\"width: 5%\">Pack</th>\n        <th class=\"batch\" style=\"width: 10%\">Batch</th>\n        <th class=\"expiry\" style=\"width: 10%\">Expiry</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for line in data.invoice.lines.nodes -%}\n      <tr class=\"body_value\">\n        <td class=\"line_number\">{{ loop.index }}</td>\n        <td class=\"location\">{{ line.locationName }}</td>\n        <td class=\"item_code\">{{ line.itemCode }}</td>\n        <td class=\"item_name\">{{ line.itemName }}</td>\n        <td class=\"quantity\">{{ line.numberOfPacks }}</td>\n        <td class=\"issued\"></td>\n        <td class=\"pack\">{{ line.packSize }}</td>\n        <td class=\"batch\">{{ line.batch }}</td>\n        <td class=\"expiry\">{{ line.expiryDate }}</td>\n      </tr>\n      {%- endfor %}\n    </tbody>\n  </table>\n</div>"
