        "template": "<div class=\"container\">\n  <hr />\n  <table class=\"header_supplied_section\">\n    <tr>\n      <td>Supplied to:</td>\n      <td class=\"align_right\">Status: {{ data.requisition.status }}</td>\n    </tr>\n\n    <tr>\n      <td>{{ data.requisition.otherPartyName }}</td>\n      <td class=\"align_right\">Our ref: {{ data.requisition.theirReference }}</td>\n    </tr>\n\n    <tr>\n      <td>Lalitpur, Kathmandu, Nepal Opposite NIMS College</td>\n      <td class=\"align_right\">\n        Confirmed Date: {{ data.requisition.createdDatetime | date(format=\"%m/%d/%Y\") }}\n      </td>\n    </tr>\n  </table>\n\n  <table class=\"header_date_section\">\n    <tr>\n      <td></td>\n      <td class=\"align_right\">Printed date: {{ now() | date(format=\"%m/%d/%Y\") }}</td>\n    </tr>\n\n    <tr>\n      <td>Requisition Category: Category Value</td>\n      <td id=\"date\" class=\"align_right\">Authorized by:</td>\n    </tr>\n\n    <tr>\n      <td>Comments: {{ data.requisition.comment }}</td>\n      <td class=\"align_right\">Collected by:</td>\n    </tr>\n  </table>\n\n  <table class=\"body_section\" cellpadding=\"2\" cellspacing=\"0\">\n    <thead>\n      <tr class=\"body_column_label\">\n        <th class=\"line_number\" style=\"width: 5%\">Line</th>\n        <th class=\"item_code\" style=\"width: 7%\">Item code</th>\n        <th class=\"item_name\" style=\"width: 35%\">Item name</th>\n        <th class=\"quantity\" style=\"width: 7%\">Stock on Hand</th>\n        <th class=\"pack\" style=\"width: 5%\">AMC</th>\n        <th class=\"batch\" style=\"width: 8%\">Target Qty</th>\n        <th class=\"expiry\" style=\"width: 8%\">Suggested Qty</th>\n        <th class=\"sell_price\" style=\"width: 7%\">Requested Qty</th>\n        <th class=\"cost_price\" style=\"width: 7%\">Supply Qty</th>\n        <th class=\"total_extension\" style=\"width: 9%\">Remaining to Supply</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for line in data.requisition.lines.nodes -%}\n      <tr class=\"body_value\">\n        <td class=\"line_number\" style=\"width: 5%\">{{ loop.index }}</td>\n        <td class=\"item_code\" style=\"width: 7%\">{{ line.item.code }}</td>\n        <td class=\"item_name\" style=\"width: 35%\">{{ line.item.name }}</td>\n        <td class=\"quantity\" style=\"width: 8%\">{{ line.itemStats.availableStockOnHand }}</td>\n        <td class=\"pack\" style=\"width: 5%\">{{ line.itemStats.averageMonthlyConsumption }}</td>\n        <td class=\"batch\" style=\"width: 8%\">\n          {{ data.requisition.maxMonthsOfStock * line.itemStats.averageMonthlyConsumption }}\n        </td>\n        <td class=\"batch\" style=\"width: 8%\">{{ line.suggestedQuantity }}</td>\n        <td class=\"expiry\" style=\"width: 8%\">{{ line.requestedQuantity }}</td>\n        <td class=\"sell_price\" style=\"width: 7%\">{{ line.supplyQuantity }}</td>\n        <td class=\"cost_price\" style=\"width: 7%\">{{ line.remainingQuantityToSupply }}</td>\n      </tr>\n      {%- endfor %}\n    </tbody>\n  </table>\n</div>\n"
